"use client";
import { useRef } from "react";
import {
  TypeGlyphs,
  typeUnits,
  useTypeLoop,
  useTypeMotion,
  type TypographyMotionProps,
  typeInteractive,
} from "./typography-shared";
export interface TextShimmerWaveProps extends TypographyMotionProps {
  color?: string;
  highlightColor?: string;
  waveWidth?: number;
  pause?: number;
  loop?: boolean;
  lift?: number;
}
export function TextShimmerWave({
  text = "Every Mile Counts.",
  color = "#737373",
  highlightColor = "#ffffff",
  waveWidth = 4,
  pause = 0.6,
  loop = true,
  lift = 0,
  duration = 2.2,
  trigger = "load",
  ...props
}: TextShimmerWaveProps) {
  const root = useRef<HTMLSpanElement>(null),
    completed = useRef(false);
  const ambient = trigger === "load" && props.progress === undefined;
  const paint = (p: number, reduced: boolean) => {
    const units = typeUnits(root.current!);
    units.forEach((unit, i) => {
      const center = -waveWidth + p * (units.length + waveWidth * 2);
      const strength = reduced
        ? 0
        : Math.max(0, 1 - Math.abs(i - center) / Math.max(0.1, waveWidth));
      unit.style.color = `color-mix(in srgb, ${highlightColor} ${strength * 100}%, ${color})`;
      unit.style.transform = `translateY(${-lift * strength}px)`;
    });
  };
  useTypeMotion(
    root,
    {
      ...props,
      duration,
      trigger,
      progress: ambient ? 1 : props.progress,
      onComplete: ambient ? undefined : props.onComplete,
    },
    paint,
    `${text}:${color}:${highlightColor}:${waveWidth}`,
  );
  useTypeLoop(
    root,
    (time, _delta, reduced) => {
      if (trigger !== "load") return;
      if (reduced) {
        paint(1, true);
        return;
      }
      const cycle = duration * 1000 + pause * 1000;
      const p = Math.min(1, (loop ? time % cycle : time) / Math.max(1, duration * 1000));
      paint(p, false);
      if (p === 1 && !completed.current) {
        completed.current = true;
        props.onComplete?.();
      } else if (p < 1) completed.current = false;
      if (!loop && p >= 1) return false;
    },
    `${text}:${duration}:${pause}:${loop}:${props.replayKey}`,
    ambient,
  );
  return (
    <span
      ref={root}
      className={props.className}
      style={{ display: "inline-block", color, ...props.style }}
      aria-label={text}
      data-typography="text-shimmer-wave"
      {...typeInteractive(trigger)}
    >
      <span aria-hidden="true">
        <TypeGlyphs text={text} />
      </span>
    </span>
  );
}
